const defaultMembers=[{id:'aisha',name:'Aisha Rahman',initials:'AR',role:'Project lead',modules:'Finance · Procurement',color:'green'},{id:'daniel',name:'Daniel George',initials:'DG',role:'ERP consultant',modules:'Inventory · Sales',color:'blue'},{id:'sarah',name:'Sarah Thomas',initials:'ST',role:'ERP consultant',modules:'HR & Payroll · CRM',color:'lilac'},{id:'omar',name:'Omar Hassan',initials:'OH',role:'Project lead',modules:'Finance · Manufacturing',color:'peach'},{id:'priya',name:'Priya Nair',initials:'PN',role:'ERP consultant',modules:'Procurement · Inventory',color:'green'}];
let members=defaultMembers.map(m=>({...m,active:true,email:''}));
const phases=['Kickoff meeting','Master data import','Level 1 training','Level 2 training','Data entry support','Go-live support'];
