function seed(){
 const projects=[{id:'p1',name:'Al Noor Trading',code:'ERP-001',industry:'Trading & distribution',lead:'aisha',start:'2026-10-05',due:'2026-12-15',client:'Fatima Ali',email:'fatima@example.com',modules:{Finance:'aisha',Inventory:'daniel',Sales:'daniel',Procurement:'priya'},health:'On track'}, {id:'p2',name:'Meridian Manufacturing',code:'ERP-002',industry:'Manufacturing',lead:'omar',start:'2026-10-12',due:'2026-12-28',client:'James Wilson',email:'james@example.com',modules:{Finance:'omar',Inventory:'priya',Manufacturing:'omar'},health:'At risk'}, {id:'p3',name:'Greenfield Healthcare',code:'ERP-003',industry:'Healthcare',lead:'aisha',start:'2026-10-20',due:'2027-01-10',client:'Leena Mathew',email:'leena@example.com',modules:{Finance:'aisha','HR & Payroll':'sarah',Procurement:'priya'},health:'On track'}, {id:'p4',name:'Atlas Retail Group',code:'ERP-004',industry:'Retail & e-commerce',lead:'omar',start:'2026-11-01',due:'2027-01-25',client:'Khalid Ahmed',email:'khalid@example.com',modules:{Inventory:'daniel',Sales:'daniel',CRM:'sarah'},health:'On track'}];
 const tasks=[];
 return {projects,tasks,meetings:[{id:'m1',title:'Inventory · Data validation',project:'p1',module:'Inventory',date:'2026-11-12',time:'10:00',duration:60,assignee:'daniel',type:'Client visit',location:'Client office · Doha',notes:'Review opening stock balances with the warehouse team.'},{id:'m2',title:'Finance · Level 2 training',project:'p2',module:'Finance',date:'2026-11-12',time:'13:30',duration:90,assignee:'omar',type:'Training',location:'Online',notes:'Additional practice for month-end closing.'},{id:'m3',title:'Project kickoff',project:'p4',module:'General',date:'2026-11-13',time:'09:00',duration:60,assignee:'omar',type:'Kickoff',location:'Client office',notes:'Confirm scope, milestones and client owners.'}],activity:[]};}
if(!data||!Array.isArray(data.projects)){data=seed();save();}
// One-time task-only reset explicitly requested by the workspace owner.
if(data.taskReset20261117!==true){data.tasks=[];data.taskReset20261117=true;save();}
// Clear existing activity once, as requested by the workspace owner.
if(data.activityReset20261117!==true){data.activity=[];data.activityReset20261117=true;save();}
data.members=Array.isArray(data.members)?data.members:members;members=data.members;members.forEach(m=>{if(m.active===undefined)m.active=true;});save();
const permissionLabels={viewAllProjects:'View all projects and tasks',createProjects:'Create projects',assignTasks:'Allocate and reassign tasks',deleteTasks:'Delete tasks',deleteProjects:'Delete projects and their records',deleteMeetings:'Delete calendar meetings',manageModules:'Change module ownership',scheduleMeetings:'Schedule meetings',updateTasks:'Update task status and notes',manageTeam:'Manage team profiles and roles',exportReports:'Export reports'};
const roleNames=['Project manager','Project lead','ERP consultant'];
const defaultPermissions={
 'Project manager':{deleteProjects:true,deleteMeetings:true,deleteTasks:true,viewAllProjects:true,createProjects:true,assignTasks:true,manageModules:true,scheduleMeetings:true,updateTasks:true,manageTeam:true,exportReports:true},
 'Project lead':{deleteProjects:false,deleteMeetings:false,deleteTasks:false,viewAllProjects:false,createProjects:false,assignTasks:true,manageModules:true,scheduleMeetings:true,updateTasks:true,manageTeam:false,exportReports:true},
 'ERP consultant':{deleteProjects:false,deleteMeetings:false,deleteTasks:false,viewAllProjects:false,createProjects:false,assignTasks:false,manageModules:false,scheduleMeetings:false,updateTasks:true,manageTeam:false,exportReports:false}
};
data.rolePermissions=data.rolePermissions||JSON.parse(JSON.stringify(defaultPermissions));roleNames.forEach(role=>{data.rolePermissions[role]=data.rolePermissions[role]||{...defaultPermissions[role]};for(const key of ['deleteTasks','deleteProjects','deleteMeetings'])if(data.rolePermissions[role][key]===undefined)data.rolePermissions[role][key]=defaultPermissions[role][key];});save();
function currentRole(){return state.role==='manager'?'Workspace owner':person(state.consultant).role;}
function roleAllows(key){return state.role==='manager'||(person(state.consultant).active!==false&&data.rolePermissions[currentRole()]?.[key]===true);}
function canViewProject(p){return !!p&&(roleAllows('viewAllProjects')||p.lead===state.consultant||Object.values(p.modules).includes(state.consultant)||data.tasks.some(t=>t.project===p.id&&t.assignee===state.consultant));}
function projectScope(pid){let p=project(pid);return !!p&&(roleAllows('viewAllProjects')||p.lead===state.consultant||Object.values(p.modules).includes(state.consultant)||data.tasks.some(t=>t.project===pid&&t.assignee===state.consultant));}
function can(key,pid){return roleAllows(key)&&(!pid||projectScope(pid));}
function canViewTask(t){return roleAllows('viewAllProjects')||t.assignee===state.consultant||(currentRole()==='Project lead'&&project(t.project)?.lead===state.consultant);}
function canEditTask(t){return can('updateTasks',t.project)&&(t.assignee===state.consultant||can('assignTasks',t.project));}
function canDeleteTask(t){return !!t&&canViewTask(t)&&can('deleteTasks',t.project);}
function canViewMeeting(m){return roleAllows('viewAllProjects')||m.assignee===state.consultant||(currentRole()==='Project lead'&&project(m.project)?.lead===state.consultant);}
function assignmentProjects(key){return data.projects.filter(p=>can(key,p.id));}
function denied(){return '<div class="panel empty">This role does not have permission to access this page. Use the demo selector to return to the workspace owner.</div>';}
function permissionsView(){if(state.role!=='manager')return denied();return heading('Workspace settings','Role permissions','Choose what each role can do, then assign a role in Team management.')+`<div class="notice"><strong>Prototype permissions:</strong> these settings control demo views in this browser. They are not secure access controls. Individual logins and server-side authorization are still required for team use. The workspace owner retains full access and alone can edit this setup.</div><form id="permissionForm"><div class="panel"><div class="panelhead"><h2>Role permission matrix</h2><button class="btn primary" type="submit">${icon('check')} Save permissions</button></div><div class="tablewrap"><table class="permissiontable"><thead><tr><th>Permission</th>${roleNames.map(r=>`<th>${r}</th>`).join('')}</tr></thead><tbody>${Object.entries(permissionLabels).map(([key,label])=>`<tr><td>${label}</td>${roleNames.map((role,i)=>`<td><input aria-label="${label} for ${role}" type="checkbox" name="${i}_${key}" ${data.rolePermissions[role]?.[key]?'checked':''}></td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="rowfoot">Project leads see their projects and assignments. Consultants see assigned projects and their own tasks. “View all” grants workspace-wide visibility; other actions apply within accessible projects.</div></div></form><div class="sectiontitle"><h2>Assign roles to people</h2><button class="btn" data-nav="team">${icon('team')} Team management</button></div><p class="sub">Open a member’s Edit profile, change their role, and save. Existing assignments and completed work remain linked to that member.</p>`;}
function savePermissions(f){if(state.role!=='manager')return false;let next={};roleNames.forEach((r,i)=>{next[r]={};Object.keys(permissionLabels).forEach(key=>next[r][key]=f.get(`${i}_${key}`)==='on');});data.rolePermissions=next;save();toast('Role permissions saved. Select a team member to preview their access.');render();return true;}
function activeMembers(){return members.filter(m=>m.active!==false);}
function save(){try{localStorage.setItem('implement.erp.v1',JSON.stringify(data));}catch{toast('Browser storage is unavailable. Changes may not persist.');}}
function person(id){if(id==='workspace-owner')return {id,name:'Rajesh’s work space',initials:'RW',color:'green',role:'Workspace owner'};return members.find(m=>m.id===id)||members[0];}function project(id){return data.projects.find(p=>p.id===id);}
function avatar(id,large=false){const m=person(id);return `<span class="avatar ${m.color} ${large?'large':''}" title="${esc(m.name)}">${esc(m.initials)}</span>`;}
function tasksFor(p){return data.tasks.filter(t=>t.project===p);}
function progress(p){const ts=tasksFor(p);return ts.length?Math.round(ts.filter(t=>t.status==='Completed').length/ts.length*100):0;}
function projectIsComplete(p){return tasksFor(p.id).length>0&&progress(p.id)===100&&(p.companyWiseProjectTrackingRequired!==true||!p.companies?.length||p.companies.every(c=>c.goLiveStatus==='Live'));}
function risk(p){return tasksFor(p).some(t=>t.status==='More visits needed');}
function badge(s){return `<span class="badge ${s==='At risk'||s==='More visits needed'||s==='More sessions needed'||s==='Awaiting client confirmation'||s==='Open — update manager later'||s==='On hold'?'amber':s==='In progress'?'blue':s==='To do'||s==='Not ready'?'gray':''}">${esc(s)}</span>`;}
function fmt(d,opts={day:'numeric',month:'short'}){return new Date(d+'T12:00:00').toLocaleDateString('en-GB',opts);}
function today(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Qatar',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());}
function stamp(at){return new Date(at).toLocaleString('en-GB',{timeZone:'Asia/Qatar',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});}
function due(t){return t.status!=='Completed'&&t.due<today();}
function activity(who,text,p){data.activity.unshift({id:crypto.randomUUID(),who,text,project:p,at:new Date().toISOString()});save();}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(window.toaster);window.toaster=setTimeout(()=>$('#toast').classList.remove('show'),3200);}
function navigate(page,p=null){state.page=page;state.project=p;state.query='';state.tab='all';render();window.scrollTo({top:0,behavior:'smooth'});}
function options(list,selected){return (list===members?members.filter(m=>m.active!==false||m.id===selected):list).map(x=>typeof x==='string'?`<option ${x===selected?'selected':''} value="${esc(x)}">${esc(x)}</option>`:`<option ${x.id===selected?'selected':''} value="${x.id}">${esc(x.name)}</option>`).join('');}
function visibleTasks(){return data.tasks.filter(t=>(canViewTask(t))&&(state.projectFilter==='all'||t.project===state.projectFilter)&&(state.moduleFilter==='all'||t.module===state.moduleFilter)&&(state.taskFilter==='all'||(state.taskFilter==='overdue'?due(t):t.status===state.taskFilter))&&`${t.title} ${t.module} ${project(t.project)?.name} ${person(t.assignee).name}`.toLowerCase().includes(state.query.toLowerCase()));}
function shell(){const consultant=state.role==='consultant';let title={overview:'Overview',projects:'Projects',tasks:consultant?'My tasks':'Task allocation',meetings:'Meetings',team:'Team management',permissions:'Role permissions',planning:'Project plan',daily:'Daily allocations',performance:'Performance',connection:'Database & sign-in','module-master':'Module master','activity-master':'Activity master',activity:'Activity log',detail:'Projects'}[state.page];return `<div class="shell"><aside class="sidebar"><div class="brand"><span class="brandmark"><i></i><i></i><i></i></span>implement<span style="color:#a4c693">.</span></div><div class="workspace"><span class="square">PM</span><div>My Project Management<small>Implementation workspace</small></div>${icon('down')}</div><div class="navlabel">WORKSPACE</div><nav class="nav">${[['overview','grid','Overview'],['projects','folder','Projects'],['tasks','check',consultant?'My tasks':'Task allocation'],['meetings','calendar','Meetings'],['team','team','Team management'],['activity','activity','Activity log'],['permissions','check','Role permissions']].filter(([id])=>id==='permissions'?state.role==='manager':id==='team'?can('manageTeam'):id==='overview'?roleAllows('viewAllProjects'):true).map(([id,i,label])=>`<button data-nav="${id}" class="${state.page===id||state.page==='detail'&&id==='projects'?'active':''}">${icon(i)}${label}${id==='projects'?`<span class="count">${data.projects.filter(canViewProject).length}</span>`:''}</button>`).join('')}</nav><div class="sidebottom"><div class="sidecall">${icon('help')} <strong>Built around your delivery</strong><p>From the first kickoff to a confident go-live. Every step, together.</p></div><div class="profile">${consultant?avatar(state.consultant):'<span class="avatar">RW</span>'}<div>${consultant?esc(person(state.consultant).name):"Rajesh’s work space"}<small>${consultant?esc(currentRole()):'Workspace owner'}</small></div></div></div></aside><main class="main"><header class="topbar"><div class="crumb"><button class="mobiletoggle" data-action="menu" aria-label="Toggle navigation">${icon('menu')}</button>Workspace ${icon('chevron')} <b>${title}</b></div><div class="topright"><label class="search">${icon('search')}<input id="globalSearch" placeholder="Search projects & tasks" aria-label="Search projects and tasks" value="${esc(state.query)}"><span class="key">⌕</span></label><select class="toprole" id="roleSelect" aria-label="Demo role"><option value="manager" ${!consultant?'selected':''}>Workspace owner · demo</option>${activeMembers().map(m=>`<option value="${m.id}" ${consultant&&state.consultant===m.id?'selected':''}>${esc(m.name)} · ${esc(m.role)} · demo</option>`).join('')}</select><span class="avatar">${consultant?esc(person(state.consultant).initials):'RW'}</span></div></header><div class="content" id="view"></div></main></div>`;}
function heading(eyebrow,title,sub,buttons=''){return `<div class="pageheading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="sub">${sub}</p></div><div class="actions">${buttons}</div></div>`;}
function newProjectButton(){return can('createProjects')?`<button class="btn primary" data-action="new-project">${icon('plus')} New project</button>`:'';}
function stat(label,value,foot,ico){return `<div class="stat"><div class="stathead">${label}${icon(ico)}</div><div class="statvalue">${value}</div><div class="statfoot">${foot}</div></div>`;}
function projectTable(ps,full=false){return `<div class="tablewrap"><table><thead><tr><th>Project / Client</th><th>Status</th><th>Progress</th><th>Team</th><th>Go-live</th>${full?'<th>Project lead</th>':''}<th></th></tr></thead><tbody>${ps.map(p=>`<tr class="clickable" data-project="${p.id}"><td><div class="projectname"><span class="projecticon">${icon('building')}</span><div><strong>${esc(p.name)}</strong><small>${p.code} &nbsp;·&nbsp; ${Object.keys(p.modules).length} modules</small></div></div></td><td>${badge(projectIsComplete(p)?'Completed':risk(p.id)?'At risk':'On track')}</td><td><div class="proglabel"><span>${progress(p.id)}%</span></div><div class="progress"><i style="width:${progress(p.id)}%"></i></div></td><td><div class="people">${[...new Set([p.projectManager,p.lead,...Object.values(p.modules),...Object.values(p.moduleTeams||{}).flat()].filter(Boolean))].map(x=>avatar(x)).join('')}</div></td><td style="color:#7b8872;font-size:10px">${fmt(p.due)}</td>${full?`<td>${esc(person(p.lead).name)}</td>`:''}<td>${can('managePlans',p.id)?`<button class="btn small" data-edit-project="${esc(p.id)}">Edit project</button>`:''}<button aria-label="Open ${esc(p.name)}">${icon('chevron')}</button>${can('deleteProjects',p.id)?`<button class="textlink delete-action" data-delete-project="${p.id}">Delete project</button>`:''}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">No projects match this view.</td></tr>'}</tbody></table></div>`;}
function workload(){return `<div class="workload">${members.slice(0,4).map(m=>{let ts=data.tasks.filter(t=>t.assignee===m.id&&t.status!=='Completed');let active=ts.filter(t=>t.status!=='To do').length;return `<div class="workrow">${avatar(m.id)}<div class="workperson">${esc(m.name)}<small>${m.role}</small></div><div class="workbar"><span>${active} active / ${ts.length} open</span><div class="progress"><i style="width:${Math.min(100,active/8*100)}%;background:${active>6?'#c7a273':'#8fae7b'}"></i></div></div></div>`}).join('')}</div>`;}
function activityList(limit=4){return `<div class="activity">${data.activity.filter(a=>roleAllows('viewAllProjects')||(currentRole()==='Project lead'&&project(a.project)?.lead===state.consultant)||a.who===state.consultant).slice(0,limit).map(a=>`<div class="activityitem">${avatar(a.who)}<p><b>${esc(person(a.who).name)}</b> ${esc(a.text)}<br><b>${esc(project(a.project)?.name||'Workspace')}</b><time>${stamp(a.at)} · Qatar</time></p></div>`).join('')||'<p class="empty">Updates will appear here.</p>'}</div>`;}
function overview(){let ts=data.tasks,rs=ts.filter(t=>['More visits needed','More sessions needed'].includes(t.status));let upcoming=data.meetings.filter(m=>m.date>=today()).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));let ps=data.projects.filter(p=>state.tab==='risk'?risk(p.id):state.tab==='completed'?projectIsComplete(p):!projectIsComplete(p)).filter(p=>p.name.toLowerCase().includes(state.query.toLowerCase()));return heading('Your delivery, at a glance','Every project. Moving forward.','A clear view of your implementations, people, and next steps.',`${can('exportReports')?`<button class="btn" data-action="export">${icon('download')} Export report</button>`:''}${newProjectButton()}`)+`<div class="stats">${stat('Active projects',data.projects.filter(p=>!projectIsComplete(p)).length,`<span>${data.projects.filter(canViewProject).length}</span> total implementations`,'folder')}${stat('Tasks in progress',ts.filter(t=>t.status==='In progress').length,`<span>${ts.filter(t=>t.status==='Completed').length} completed</span> across projects`,'check')}${stat('Sessions requested',rs.length,`<span class="warn">Action needed</span> consultant follow-ups`,'alert')}${stat('Consultants assigned',new Set(ts.map(t=>t.assignee)).size,`<span>${members.filter(m=>m.role==='Project lead').length} project leads</span> on the team`,'team')}</div><div class="dashboardgrid"><div><section class="panel"><div class="panelhead"><h2>Project portfolio</h2><button class="textlink" data-nav="projects">All projects ${icon('arrow')}</button></div><div class="tabrow">${[['all','Active projects',data.projects.filter(p=>!projectIsComplete(p)).length],['risk','Needs attention',data.projects.filter(p=>risk(p.id)).length],['completed','Completed',data.projects.filter(p=>projectIsComplete(p)).length]].map(([id,l,n])=>`<button class="tab ${state.tab===id?'active':''}" data-tab="${id}">${l}<span>${n}</span></button>`).join('')}</div>${projectTable(ps)}<div class="rowfoot"><span>${ps.length} projects in this view</span><span>Click a project to explore ${icon('arrow')}</span></div></section><div class="bottomgrid"><section class="panel"><div class="panelhead"><h2>Team at a glance</h2><button class="textlink" data-nav="team">View team ${icon('arrow')}</button></div>${workload()}</section><section class="panel"><div class="panelhead"><h2>Latest updates</h2><button class="textlink" data-nav="activity">View all ${icon('arrow')}</button></div>${activityList(3)}</section></div></div><aside class="rightcol"><section class="panel"><div class="panelhead"><h2>Coming up</h2><span class="todaydate">Qatar time</span></div><div class="timeline">${upcoming.slice(0,3).map((m,i)=>`<div class="meeting"><div class="timebox"><b>${m.hoursOnly?'Hours only':m.time}</b><br>${m.date===today()?'Today':fmt(m.date)}</div><div class="dotbar ${i===1?'orange':''}"></div><div><button style="padding:0;text-align:left" data-meeting="${m.id}"><div class="meetingtitle">${esc(m.title)}</div><small>${esc(project(m.project)?.name)}</small></button>${badge(m.type)}<div class="meetingpeople">${avatar(m.assignee)} <small style="display:inline;margin-left:5px">${m.duration} min</small></div></div></div>`).join('')||'<p class="empty">No upcoming meetings.</p>'}</div><div class="rowfoot"><button class="textlink" data-nav="meetings">Open meeting schedule ${icon('arrow')}</button></div></section><section class="panel attention"><h3>${icon('alert')} A little attention goes a long way</h3><p>${rs.length?`${rs.length} task${rs.length===1?' needs':'s need'} an additional client visit. Review the consultant’s note and plan the next step.`:'No additional visits requested. Your team’s updates will appear here.'}</p><button class="textlink" data-action="review-visits">Review requests ${icon('arrow')}</button></section></aside></div>`;}
function projectsView(){let ps=data.projects.filter(canViewProject).filter(p=>(`${p.name} ${p.code} ${p.industry}`).toLowerCase().includes(state.query.toLowerCase())&&(state.tab==='all'||(state.tab==='risk'?risk(p.id):projectIsComplete(p))));return heading('Project portfolio','A home for every implementation.','Assign leads, connect modules to consultants, and keep delivery on track.',newProjectButton())+`<div class="panel"><div class="panelhead"><h2>All implementations <span style="color:#8f9e83;font-weight:400">(${ps.length})</span></h2><select id="projectTab" class="toprole"><option value="all">All projects</option><option value="risk" ${state.tab==='risk'?'selected':''}>Needs attention</option><option value="completed" ${state.tab==='completed'?'selected':''}>Completed</option></select></div>${projectTable(ps,true)}</div>`;}
function taskTable(ts,showProject=true){return `<div class="tablewrap"><table><thead><tr><th>Task / ${showProject?'Project':'Phase'}</th><th>Module</th><th>Assigned to</th><th>Due date</th><th>Status</th><th></th></tr></thead><tbody>${ts.map(t=>`<tr><td><button class="tasktitle" style="text-align:left;padding:0" data-task="${t.id}">${esc(t.title)}<small>${showProject?esc(project(t.project)?.name):t.priority+' priority'}</small></button></td><td>${esc(t.module)}</td><td><div style="display:flex;align-items:center;gap:8px">${avatar(t.assignee)}<span>${esc(person(t.assignee).name.split(' ')[0])}</span></div></td><td style="color:${due(t)?'#b57a56':'#7c8b71'}">${fmt(t.due)}${due(t)?'<small style="display:block;margin-top:4px;font-size:9px">Overdue</small>':''}</td><td>${badge(t.status)}</td><td><button class="textlink" data-task="${t.id}">${canEditTask(t)?'Update':'Details'} ${icon('chevron')}</button>${can('assignTasks',t.project)?`<button class="textlink whatsapp-action" data-whatsapp-task="${t.id}">Send via WhatsApp</button>`:''}${canDeleteTask(t)?`<button class="textlink delete-action" data-delete-task="${t.id}">Delete task</button>`:''}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No tasks match these filters.</td></tr>'}</tbody></table></div>`;}
function taskCards(ts){return `<div class="taskcards">${ts.map(t=>`<div class="taskcard"><div style="display:flex;justify-content:space-between">${badge(t.status)}<span class="eyebrow" style="font-size:9px">${esc(t.module)}</span></div><h3>${esc(t.title)}</h3><p class="meta">${esc(project(t.project)?.name)}<br>Due ${fmt(t.due)} · ${t.priority} priority</p><div class="cardfoot">${avatar(t.assignee)}<button class="textlink" data-task="${t.id}">View & update ${icon('arrow')}</button>${can('assignTasks',t.project)?`<button class="textlink whatsapp-action" data-whatsapp-task="${t.id}">WhatsApp</button>`:''}${canDeleteTask(t)?`<button class="textlink delete-action" data-delete-task="${t.id}">Delete task</button>`:''}</div></div>`).join('')||'<div class="empty">No tasks match these filters.</div>'}</div>`;}
function tasksView(){let ts=visibleTasks();let allocator=roleAllows('assignTasks');return heading(allocator?'Delivery operations':'Consultant workspace',allocator?'The right task. The right person.':`Your work, ${esc(person(state.consultant).name.split(' ')[0])}.`,allocator?'Allocate work and turn consultant updates into clear project progress.':'Review your assignments, record outcomes, and request another client visit.',(can('exportReports')?`<button class="btn" data-action="export">${icon('download')} Export report</button>`:'')+(allocator?`<button class="btn primary" data-action="new-task">${icon('plus')} Allocate task</button>`:''))+`<div class="filters"><select id="taskProject" aria-label="Filter project"><option value="all">All projects</option>${options(data.projects.filter(canViewProject),state.projectFilter)}</select><select id="taskStatus" aria-label="Filter task status"><option value="all">All statuses</option>${options(statuses,state.taskFilter)}<option value="overdue" ${state.taskFilter==='overdue'?'selected':''}>Overdue</option></select><select id="taskModule" aria-label="Filter module"><option value="all">All modules</option>${options(['General',...modules],state.moduleFilter)}</select><div style="flex:1"></div><span class="sub">${ts.length} tasks</span><button class="btn small" data-action="task-layout">${icon(state.taskLayout==='list'?'grid':'file')} ${state.taskLayout==='list'?'Cards':'List'}</button></div>${state.taskLayout==='list'?`<div class="panel">${taskTable(ts)}</div>`:taskCards(ts)}`;}
function detailView(){let p=project(state.project);if(!p)return projectsView();if(!canViewProject(p))return denied();let ts=tasksFor(p.id).filter(t=>canViewTask(t));return heading(p.code,esc(p.name),`${esc(p.industry)} · Client contact: ${esc(p.client)}`,`<button class="btn" data-nav="projects">${icon('folder')} All projects</button>${can('deleteProjects',p.id)?`<button class="btn" data-delete-project="${p.id}">Delete project</button>`:''}${can('assignTasks',p.id)?`<button class="btn primary" data-action="new-task" data-for="${p.id}">${icon('plus')} Allocate task</button>`:''}`)+`<div class="detailhead"><span class="projecticon">${icon('building')}</span><div style="flex:1"><h2>Implementation progress</h2><div class="sub">${tasksFor(p.id).filter(t=>t.status==='Completed').length} of ${tasksFor(p.id).length} tasks completed · ${progress(p.id)}%</div><div class="progress"><i style="width:${progress(p.id)}%"></i></div></div>${badge(risk(p.id)?'At risk':projectIsComplete(p)?'Completed':'On track')}</div><div class="projectmeta"><label>Project in charge &nbsp;${can('manageModules',p.id)?`<select id="projectLead">${options(members,p.lead)}</select>`:esc(person(p.lead).name)}</label><span>Kickoff: <b>${fmt(p.start)}</b></span><span>Target go-live: <b>${fmt(p.due)}</b></span></div><div class="sectiontitle"><h2>Implementation journey</h2><span class="sub">Progress from completed tasks</span></div><div class="stages">${phases.map((phase,i)=>{let stage=tasksFor(p.id).filter(t=>t.title===phase);let complete=stage.filter(t=>t.status==='Completed').length;return `<div class="stage ${stage.length&&complete===stage.length?'done':''}"><b>${String(i+1).padStart(2,'0')} ${stage.length&&complete===stage.length?'✓':''}</b>${phase}<div style="margin-top:8px;font-size:9px;color:#99a08e">${complete}/${stage.length} complete</div></div>`}).join('')}</div><div class="sectiontitle"><h2>Module ownership</h2><span class="sub">${Object.keys(p.modules).length} modules</span></div><div class="modulegrid">${Object.entries(p.modules).map(([m,a])=>{let mts=tasksFor(p.id).filter(t=>t.module===m);let pr=mts.length?Math.round(mts.filter(t=>t.status==='Completed').length/mts.length*100):0;return `<div class="modulecard"><div style="display:flex;justify-content:space-between;font-size:12px;font-weight:600">${esc(m)}<span style="color:#8b9980;font-size:10px">${pr}%</span></div><div class="progress" style="margin-top:12px"><i style="width:${pr}%"></i></div>${can('manageModules',p.id)?`<select data-module-owner="${esc(m)}" aria-label="${esc(m)} consultant">${options(members,a)}</select>`:`<div style="margin-top:12px;font-size:11px;color:#859477">${esc(person(a).name)}</div>`}</div>`}).join('')}</div><div class="sectiontitle"><h2>${roleAllows('viewAllProjects')||currentRole()==='Project lead'?'Project tasks':'My project tasks'}</h2><span class="sub">${ts.length} assignments</span></div><div class="panel">${taskTable(ts,false)}</div>`;}
function meetingsView(){let ms=data.meetings.filter(m=>canViewMeeting(m)).filter(m=>(m.title+' '+project(m.project)?.name).toLowerCase().includes(state.query.toLowerCase())).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));return heading('Client connections','Make every visit count.','Kickoffs, training sessions, and follow-ups — one shared schedule. All times in Qatar.',roleAllows('scheduleMeetings')?`<button class="btn primary" data-action="new-meeting">${icon('plus')} Schedule meeting</button>`:'')+`<div class="calendarlist">${ms.map(m=>`<div class="calcard"><div class="caldate">${fmt(m.date,{month:'short'})}<b>${new Date(m.date+'T12:00:00').getDate()}</b>${new Date(m.date+'T12:00:00').getFullYear()}</div><div class="calinfo"><h3>${esc(m.title)}</h3><p>${esc(project(m.project)?.name)} · ${esc(m.module)}<br>${m.hoursOnly?'Hours only':m.time} · ${m.duration} min · ${esc(m.location)}</p></div><div>${avatar(m.assignee)} <span style="font-size:11px;margin-left:7px">${esc(person(m.assignee).name)}</span></div><div class="actions">${badge(m.type)}<button class="btn small" data-meeting="${m.id}">Details ${icon('chevron')}</button>${can('deleteMeetings',m.project)?`<button class="btn small" data-delete-meeting="${m.id}">Delete meeting</button>`:''}</div></div>`).join('')||'<div class="panel empty">No meetings scheduled for this view.</div>'}</div>`;}
function teamView(){if(!can('manageTeam'))return denied();let manager=can('manageTeam');return heading('People & capacity','Your people. Your delivery team.','Create team members, manage module expertise, and view their workload.',manager?`<button class="btn primary" data-action="add-member">${icon('plus')} Add team member</button>`:'')+`<div class="notice">Team profiles are saved in this browser. Adding a member makes them available for assignments; it does not create a login or send an invitation.</div><div class="teamgrid">${members.filter(m=>(m.name+' '+(m.email||'')+' '+m.role+' '+m.modules).toLowerCase().includes(state.query.toLowerCase())).map(m=>{let ts=data.tasks.filter(t=>t.assignee===m.id);let open=ts.filter(t=>t.status!=='Completed');return `<div class="teamcard"><div style="display:flex;justify-content:space-between;align-items:center">${avatar(m.id,true)}${badge(m.active===false?'Inactive':'Active')}</div><h3>${esc(m.name)}</h3><p>${esc(m.role)}<br>${esc(m.email||'No email added')}<br>${m.whatsapp?'WhatsApp: '+esc(m.whatsapp)+'<br>':''}${esc(m.modules||'No module expertise selected')}</p><div class="proglabel"><span>${ts.filter(t=>t.status==='Completed').length} completed</span><span>${open.length} open</span></div><div class="progress"><i style="width:${ts.length?(ts.length-open.length)/ts.length*100:0}%"></i></div><p>${new Set(ts.map(t=>t.project)).size} projects · ${open.filter(t=>t.status==='More visits needed').length} visit requests</p><div style="display:flex;gap:8px;flex-wrap:wrap">${manager?`<button class="btn small" data-edit-member="${m.id}">Edit profile</button><button class="btn small" data-toggle-member="${m.id}">${m.active===false?'Reactivate':'Deactivate'}</button>`:''}${m.active!==false?`<button class="textlink" data-consultant="${m.id}" style="margin-top:10px">Preview workspace ${icon('arrow')}</button>`:''}</div></div>`}).join('')||'<div class="empty">No team members match your search.</div>'}</div>`;}
function memberForm(id){if(!can('manageTeam'))return;let m=members.find(m=>m.id===id);formModal(m?'Edit team member':'Add team member','Create an assignment profile for your team. This does not create a staff login.',field('Full name',`<input name="name" required maxlength="80" value="${esc(m?.name||'')}" placeholder="Consultant or project lead name">`)+field('Work email',`<input name="email" type="email" required maxlength="180" value="${esc(m?.email||'')}" placeholder="name@company.com">`)+field('WhatsApp number (optional)',`<input name="whatsapp" type="tel" maxlength="30" value="${esc(m?.whatsapp||'')}" placeholder="+974 12345678"><span class="helper">Include + and the country code. Used for individual task messages.</span>`)+field('Role',`<select name="role">${options(roleNames.filter(r=>data.roleMaster?.find(x=>x.name===r)?.active!==false||r===m?.role).map(r=>({id:r,name:roleLabel(r)})),m?.role||'ERP consultant')}</select>`)+field('Avatar color',`<select name="color">${options(['green','blue','lilac','peach'],m?.color||'green')}</select>`)+`<div class="field full">Module expertise<div class="checks">${modules.filter(module=>typeof moduleEnabled==='undefined'||moduleEnabled(module)||(m?.modules||'').split(' · ').includes(module)).map(module=>`<label class="check"><input type="checkbox" name="expertise" value="${esc(module)}" ${(m?.modules||'').split(' · ').includes(module)?'checked':''}>${esc(module)}</label>`).join('')}</div><span class="helper">Expertise is a planning reference. Assign module ownership within each project.</span></div>`,'Save team member',f=>{if(!can('manageTeam'))return false;let name=f.get('name').trim(),email=f.get('email').trim().toLowerCase();if(!name||!email){toast('Enter the team member’s name and email.');return false;}if(members.some(x=>x.id!==id&&x.email?.toLowerCase()===email)){toast('A team member with this email already exists.');return false;}let rawPhone=f.get('whatsapp').trim(),whatsapp=normalizeWhatsApp(rawPhone);if(rawPhone&&!whatsapp){toast('Enter an international WhatsApp number with + and country code.');return false;}let values={name,email,whatsapp,role:f.get('role'),color:f.get('color'),modules:f.getAll('expertise').join(' · '),initials:name.split(/\s+/).slice(0,2).map(w=>Array.from(w)[0]).join('').toUpperCase()};if(m)Object.assign(m,values);else{m={id:crypto.randomUUID(),...values,active:true};members.push(m);}save();toast(id?'Team profile updated.':'Team member added and available for assignments.');render();});}
function toggleMember(id){if(!can('manageTeam'))return;let m=members.find(m=>m.id===id);if(!m)return;if(m.active!==false){let open=data.tasks.filter(t=>t.assignee===id&&t.status!=='Completed').length;let ownership=data.projects.filter(p=>!projectIsComplete(p)&&(p.lead===id||p.projectManager===id||Object.values(p.modules).includes(id)||Object.values(p.moduleTeams||{}).some(ids=>ids.includes(id)))).length;let meetings=data.meetings.filter(x=>x.assignee===id&&x.date>=today()).length;if(open||ownership||meetings){modal('Reassign work before deactivating',`<div class="modalbody"><p>${esc(m.name)} still has ${open} open tasks, ${ownership} active project responsibilities, and ${meetings} upcoming meetings. Reassign the work or complete it before deactivating this profile.</p><p>Completed task history will remain available.</p></div>`,`<div class="modalfoot"><button class="btn primary" data-close>Understood</button></div>`);return;}}m.active=m.active===false;save();render();toast(m.active?'Team member reactivated.':'Team member deactivated. Completed history is preserved.');}
function footer(){return `<footer class="footer"><span><i></i> Interactive prototype · saved on this browser</span><span>Implement · A little structure. A lot of progress.</span></footer>`;}
function render(){ $('#app').innerHTML=shell();renderView();}
function renderView(){let page=!roleAllows('viewAllProjects')&&state.page==='overview'?'tasks':state.page;$('#view').innerHTML=({overview,projects:projectsView,tasks:tasksView,detail:detailView,meetings:meetingsView,team:teamView,permissions:permissionsView,activity:()=>heading('Workspace activity','Every update tells a story.','Task outcomes and assignment changes, recorded as they happen.')+`<div class="panel">${activityList(100)}</div>`}[page]||overview)()+footer();if(page==='permissions'&&state.role==='manager')$('#permissionForm').onsubmit=e=>{e.preventDefault();savePermissions(new FormData(e.target));};}
function modal(title,body,foot=''){let d=$('#modal');d.innerHTML=`<div class="modalhead"><h2>${title}</h2><button type="button" class="btn small" data-close aria-label="Close dialog">${icon('x')} Close</button></div>${body}${foot}`;d.showModal();}
function field(label,input,full=false){return `<label class="field ${full?'full':''}">${label}${input}</label>`;}
function formModal(title,intro,body,submit,onSubmit){modal(title,`<form id="editForm"><div class="modalbody"><p>${intro}</p><div class="formgrid">${body}</div></div><div class="modalfoot"><button type="button" class="btn" data-close>Cancel</button><button type="submit" class="btn primary">${submit}</button></div></form>`);$('#editForm').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target);let result=onSubmit(f);if(result===false)return;$('#modal').close();save();renderView();if(typeof result==='function')result();};}
function newProject(){if(!can('createProjects'))return;formModal('Start a new implementation','Set the project owner and modules. Add dated company activities or apply an implementation template inside the project.',field('Client / project name','<input name="name" required maxlength="90" placeholder="e.g. Horizon Trading">')+field('Project code',`<input name="projectCode" required maxlength="50" value="${nextProjectCode()}"><span class="helper">Unique code, up to 50 characters.</span>`)+field('Project stage / activity type',`<select name="stageType" required>${typeOptions('implementation')}</select>`)+field('Customer',`<select name="customerId" required>${customerOptions()}</select><span class="helper">Maintain customers in Customer master.</span>`)+field('Industry','<input name="industry" required maxlength="70" placeholder="e.g. Trading & distribution">')+field('Project in charge',`<select name="lead">${options(members,'aisha')}</select>`)+field('Client contact','<input name="client" required maxlength="70" placeholder="Contact name">')+field('Kickoff date',`<input name="start" type="date" value="${today()}" required>`)+field('Target go-live','<input name="due" type="date" required>')+`<div class="field full">Implementation modules<div class="checks">${modules.filter(m=>typeof moduleEnabled==='undefined'||moduleEnabled(m)).map((m,i)=>`<label class="check"><input type="checkbox" name="modules" value="${esc(m)}" ${i<3?'checked':''}>${esc(m)}</label>`).join('')}</div><span class="helper">Choose a consultant / in-charge for each selected module below. Office projects may leave ERP modules unselected and use General. Configure company-specific consultants and activities inside the project.</span></div>`,'Create project',f=>{if(!can('createProjects'))return false;let enteredCode=f.get('projectCode')?.trim();if(!enteredCode||enteredCode.length>50||data.projects.some(p=>p.code?.toLowerCase()===enteredCode.toLowerCase())){toast('Enter a unique project code up to 50 characters.');return false;}if(!typeActive(f.get('stageType'))){toast('Select an active project stage.');return false;}if(!customerActive(f.get('customerId'))){toast('Select an active customer.');return false;}let ms=f.getAll('modules');if(typeof moduleEnabled!=='undefined'&&ms.some(m=>!moduleEnabled(m))){toast('Inactive modules cannot be selected for a new project.');return false;}if(!ms.length&&f.get('stageType')==='office')ms=['General'];if(!ms.length){toast('Choose at least one implementation module.');return false;}if(f.get('due')<f.get('start')){toast('Go-live must be on or after the kickoff date.');return false;}let p={id:crypto.randomUUID(),name:f.get('name').trim(),code:f.get('projectCode').trim(),stageType:f.get('stageType'),customerId:f.get('customerId'),industry:f.get('industry').trim(),lead:f.get('lead'),client:f.get('client').trim(),start:f.get('start'),due:f.get('due'),modules:Object.fromEntries(ms.map(m=>[m,f.get('lead')])),health:'On track'};if(!p.name){toast('Enter a project name.');return false;}data.projects.unshift(p);activity(p.lead,'created the implementation plan',p.id);state.page='detail';state.project=p.id;toast('Project created. Add companies and their implementation plan.');});}
function newTask(pid){let eligible=assignmentProjects('assignTasks');if(!eligible.length){toast('This role cannot allocate tasks to any projects.');return;}if(!data.projects.length){toast('Create a project first.');return;}pid=eligible.some(p=>p.id===pid)?pid:eligible[0].id;formModal('Allocate a task','Assign a phase, support request, or client follow-up to a consultant or project lead.',field('Project',`<select name="project" id="formProject">${options(assignmentProjects('assignTasks'),pid)}</select>`)+field('Module',`<select name="module" id="formModule">${options(['General',...Object.keys(project(pid).modules)],'General')}</select>`)+field('Task title','<input name="title" required maxlength="120" placeholder="e.g. Validate customer master data">',true)+field('Assigned to',`<select name="assignee">${options(members,project(pid).lead)}</select>`)+field('Due date',`<input name="due" type="date" required value="${today()}">`)+field('Priority',`<select name="priority">${options(['Low','Medium','High'],'Medium')}</select>`)+field('Initial status',`<select name="status">${options(['To do','In progress'],'To do')}</select>`)+field('Task details','<textarea name="notes" maxlength="2000" placeholder="Expected outcome, client context, and preparation needed"></textarea>',true)+`<div class="field full"><label class="check"><input type="checkbox" name="prepareWhatsApp">Prepare an individual WhatsApp message after saving</label><span class="helper">Review the message, then press Send in WhatsApp. No automatic messages are sent.</span></div>`,'Allocate task',f=>{if(!can('assignTasks',f.get('project')))return false;let t=Object.fromEntries(f);delete t.prepareWhatsApp;t.title=t.title.trim();if(!t.title){toast('Enter a task title.');return false;}Object.assign(t,{id:crypto.randomUUID(),visits:0,history:[]});data.tasks.unshift(t);activity(t.assignee,`was assigned ${t.module} · ${t.title}`,t.project);toast('Task allocated to '+person(t.assignee).name+'.');if(f.get('prepareWhatsApp')==='on')return ()=>whatsAppTask(t.id);});$('#formProject').onchange=e=>{$('#formModule').innerHTML=options(['General',...Object.keys(project(e.target.value).modules)],'General');};}
function taskDetail(id){let t=data.tasks.find(t=>t.id===id);if(!t)return;let allowed=canViewTask(t);if(!allowed){toast('This task is not assigned to this demo consultant.');return;}let editable=canEditTask(t),manage=can('assignTasks',t.project);formModal('Task details',`${esc(project(t.project)?.name)} · ${esc(t.module)} · Due ${fmt(t.due)}`,`<div class="field full"><h2>${esc(t.title)}</h2><div class="helper">${t.priority} priority · ${t.visits||0} additional visit requests</div>${manage?`<button type="button" class="btn small whatsapp-action" data-whatsapp-task="${t.id}">Send via WhatsApp</button><span class="helper"> Uses the saved assignment. Save any changes before preparing the message.</span>`:''}${canDeleteTask(t)?`<button type="button" class="btn small delete-action" data-delete-task="${t.id}">Delete task</button>`:''}</div>`+field('Assigned to',can('assignTasks',t.project)?`<select name="assignee">${options(members,t.assignee)}</select>`:`<input value="${esc(person(t.assignee).name)}" disabled>`)+field('Status',`<select name="status" id="updateStatus" ${editable?'':'disabled'}>${options(statuses,t.status)}</select>`)+field('Task instructions',`<textarea name="instructions" maxlength="2000" ${can('assignTasks',t.project)?'':'readonly'}>${esc(t.notes)}</textarea>`,true)+field('Update note',`<textarea id="updateNote" name="note" ${editable?'':'readonly'} maxlength="2000" placeholder="What was completed? If another visit is needed, explain why." ${editable&&t.status==='More visits needed'?'required':''}></textarea>`,true)+`<div class="field full helper">${t.history?.length?'<b>Recent updates</b>'+t.history.slice(-4).reverse().map(h=>`<div class="notes">${esc(h.status)} · ${stamp(h.at)}<br>${esc(h.note||'Status updated')}</div>`).join(''):'Your update will appear in the manager’s project progress and activity log.'}</div>`,editable||manage?'Save update':'Close details',f=>{let update=canEditTask(t),assign=can('assignTasks',t.project);if(!update&&!assign)return;let before=t.status;let next=update?f.get('status'):t.status;let note=update?f.get('note').trim():'';if(update&&next==='More visits needed'&&!note){toast('Add a note explaining why another visit is needed.');return false;}t.status=next;if(assign){t.assignee=f.get('assignee');t.notes=f.get('instructions');}if(next==='More visits needed'&&before!==next)t.visits=(t.visits||0)+1;t.history=t.history||[];t.history.push({at:new Date().toISOString(),status:next,note});activity(t.assignee,`updated ${t.module} · ${t.title} to ${next.toLowerCase()}${note?' — '+note:''}`,t.project);toast('Task updated. Project progress has been recalculated.');});$('#updateStatus').onchange=e=>$('#updateNote').required=editable&&e.target.value==='More visits needed';}
function newMeeting(task){let eligible=assignmentProjects('scheduleMeetings');if(!eligible.length){toast('This role cannot schedule meetings.');return;}let preferred=task?.project||state.project;let pid=eligible.some(p=>p.id===preferred)?preferred:eligible[0]?.id;if(!pid)return;formModal('Schedule a meeting','Plan a client visit, training session, or follow-up. This saves a schedule entry; invitations are not sent.',field('Project',`<select name="project" id="meetingProject">${options(assignmentProjects('scheduleMeetings'),pid)}</select>`)+field('Module',`<select name="module" id="meetingModule">${options(['General',...Object.keys(project(pid).modules)],task?.module||'General')}</select>`)+field('Meeting title',`<input name="title" required maxlength="120" value="${task?'Follow-up: '+esc(task.title):''}" placeholder="e.g. Finance training follow-up">`,true)+field('Date',`<input name="date" type="date" required value="${today()}">`)+field('Start time · Qatar','<input name="time" type="time" required value="10:00">')+field('Duration (minutes)','<input type="number" name="duration" required min="15" max="480" step="15" value="60">')+field('Consultant / lead',`<select name="assignee">${options(members,task?.assignee||project(pid).lead)}</select>`)+field('Meeting type',`<select name="type">${options(['Client visit','Training','Kickoff','Follow-up','Online'],'Client visit')}</select>`)+field('Location / meeting link','<input name="location" required maxlength="300" placeholder="Client office or meeting URL">')+field('Agenda','<textarea name="notes" maxlength="2000" placeholder="Agenda and expected outcomes"></textarea>',true),'Save meeting',f=>{if(!can('scheduleMeetings',f.get('project')))return false;let m=Object.fromEntries(f);m.duration=Number(m.duration);let start=Date.parse(`${m.date}T${m.hoursOnly?'Hours only':m.time}:00+03:00`);let clash=data.meetings.find(x=>{let other=Date.parse(`${x.date}T${x.time}:00+03:00`);return !x.hoursOnly&&x.assignee===m.assignee&&start<other+x.duration*60000&&start+m.duration*60000>other;});if(clash){toast('This consultant already has a meeting during that time.');return false;}m.id=crypto.randomUUID();data.meetings.push(m);activity(m.assignee,`was scheduled for ${m.title}`,m.project);toast('Meeting added to the schedule.');});$('#meetingProject').onchange=e=>$('#meetingModule').innerHTML=options(['General',...Object.keys(project(e.target.value).modules)],'General');}
function meetingDetail(id){let m=data.meetings.find(m=>m.id===id);if(!m||!canViewMeeting(m))return;modal(esc(m.title),`<div class="modalbody"><p>${esc(project(m.project)?.name)} · ${esc(m.module)}</p><div class="formgrid"><div class="field">Date<span class="helper">${fmt(m.date,{day:'numeric',month:'long',year:'numeric'})}</span></div><div class="field">Time<span class="helper">${m.hoursOnly?'Hours only':m.time} · ${m.duration} minutes · Qatar</span></div><div class="field">Assigned consultant<span class="helper">${esc(person(m.assignee).name)}</span></div><div class="field">Location<span class="helper">${esc(m.location)}</span></div><div class="field full">Agenda<div class="notes">${esc(m.notes||'No agenda added.')}</div></div></div></div>`,`<div class="modalfoot">${can('deleteMeetings',m.project)?`<button class="btn" data-delete-meeting="${m.id}">Delete meeting</button>`:''}<button class="btn" data-ics="${id}">${icon('download')} Download calendar event</button><button class="btn primary" data-close>Done</button></div>`);}
function confirmDeleteMeeting(id){let m=data.meetings.find(m=>m.id===id);if(!m||!canViewMeeting(m)||!can('deleteMeetings',m.project))return;modal('Delete this calendar meeting?',`<div class="modalbody"><p><strong>${esc(m.title)}</strong><br>${esc(project(m.project)?.name)}<br>${fmt(m.date)} · ${m.hoursOnly?'Hours only':m.time} Qatar time</p><p>This removes the meeting from this browser’s calendar. Tasks and projects remain. It cannot be undone. Any calendar event you previously downloaded must be removed separately from your external calendar.</p></div>`,`<div class="modalfoot"><button class="btn" data-close>Cancel</button><button class="btn danger" data-confirm-delete-meeting="${m.id}">Delete meeting</button></div>`);}
function deleteMeeting(id){let m=data.meetings.find(m=>m.id===id);if(!m||!canViewMeeting(m)||!can('deleteMeetings',m.project))return false;data.meetings=data.meetings.filter(m=>m.id!==id);activity(state.role==='manager'?'workspace-owner':state.consultant,`deleted meeting: ${m.title}`,m.project);$('#modal').close();renderView();toast('Calendar meeting deleted.');return true;}
function confirmDeleteProject(id){let p=project(id);if(!p||!canViewProject(p)||!can('deleteProjects',id))return;let tasks=tasksFor(id).length,meetings=data.meetings.filter(m=>m.project===id).length;modal('Delete this project?',`<div class="modalbody"><p><strong>${esc(p.name)}</strong> · ${esc(p.code)}</p><p>This permanently removes this project, its ${tasks} tasks and ${meetings} calendar meetings from this browser’s saved data. Team profiles and other projects stay unchanged. This cannot be undone.</p></div>`,`<div class="modalfoot"><button class="btn" data-close>Cancel</button><button class="btn danger" data-confirm-delete-project="${id}">Delete project and records</button></div>`);}
function deleteProject(id){let p=project(id);if(!p||!canViewProject(p)||!can('deleteProjects',id))return false;data.tasks=data.tasks.filter(t=>t.project!==id);data.meetings=data.meetings.filter(m=>m.project!==id);data.projects=data.projects.filter(p=>p.id!==id);activity(state.role==='manager'?'workspace-owner':state.consultant,`deleted project: ${p.name} (${p.code}) and its tasks and meetings`,id);if(state.project===id){state.project=null;state.page='projects';}if(state.projectFilter===id)state.projectFilter='all';$('#modal').close();render();toast('Project and its tasks and meetings deleted.');return true;}
function confirmDeleteTask(id){let t=data.tasks.find(t=>t.id===id);if(!canDeleteTask(t))return;modal('Delete this task?',`<div class="modalbody"><p><strong>${esc(t.title)}</strong><br>${esc(project(t.project)?.name)} · ${esc(t.module)}<br>Assigned to ${esc(person(t.assignee).name)}</p><p>This permanently removes the task, its daily allocations and actual time entries, its task update history, and its upcoming linked follow-up meetings from the saved workspace. Project progress and workload will be recalculated. This cannot be undone.</p></div>`,`<div class="modalfoot"><button class="btn" data-close>Cancel</button><button class="btn danger" data-confirm-delete-task="${t.id}">Delete task</button></div>`);}
function deleteTask(id){let t=data.tasks.find(t=>t.id===id);if(!canDeleteTask(t))return false;data.tasks=data.tasks.filter(x=>x.id!==id);data.meetings=data.meetings.filter(m=>!(m.parentTaskId===id&&m.date>=today()));activity(state.role==='manager'?'workspace-owner':state.consultant,`deleted task: ${t.module} · ${t.title}`,t.project);$('#modal').close();renderView();toast('Task deleted. Project progress and workload updated.');return true;}
function normalizeWhatsApp(value){let compact=String(value||'').trim().replace(/[\s()\-]/g,'');return /^\+[1-9]\d{6,14}$/.test(compact)?compact:'';}
function whatsAppMessage(t){let p=project(t.project),m=person(t.assignee);return [`Hi ${m.name},`,`You have been assigned a task in My Project Management.`,``,`Project: ${p?.name||''}`,`Module: ${t.module}`,`Task: ${t.title}`,`Due date: ${fmt(t.due,{day:'numeric',month:'long',year:'numeric'})}`,`Priority: ${t.priority}`,`Status: ${t.status}`,t.notes?`Details: ${t.notes}`:'',``,`Please review the assignment and update your progress in the application.`,`Application: https://implement-erp-delivery-nov12.easy-plum-8264.chatgpt.site`].filter(x=>x!==null).join('\n');}
function whatsAppUrl(t){let phone=normalizeWhatsApp(person(t.assignee).whatsapp);return phone?'https://wa.me/'+phone.slice(1)+'?text='+encodeURIComponent(whatsAppMessage(t)):null;}
function whatsAppTask(id){let t=data.tasks.find(t=>t.id===id);if(!t||!can('assignTasks',t.project)||!canViewTask(t))return;let m=person(t.assignee),url=whatsAppUrl(t);if(!url){modal('Add the consultant’s WhatsApp number',`<div class="modalbody"><p>The task is saved. ${esc(m.name)} needs a valid WhatsApp number before you can prepare an individual message.</p><p>Open Team management → Edit profile and enter the number with + and country code, such as +974 followed by the local number.</p></div>`,`<div class="modalfoot">${can('manageTeam')?`<button class="btn" data-whatsapp-edit-member="${m.id}">Edit consultant profile</button>`:''}<button class="btn primary" data-close>Done</button></div>`);return;}modal('Send task via WhatsApp',`<div class="modalbody"><p>To <strong>${esc(m.name)}</strong> · ${esc(m.whatsapp)}</p><label class="field">Message preview<textarea class="whatsapp-preview" readonly>${esc(whatsAppMessage(t))}</textarea></label><p style="margin-top:16px">Open WhatsApp, review the recipient and message, then press Send there. Opening the link does not confirm delivery. The consultant’s application access must be set up separately.</p></div>`,`<div class="modalfoot"><button class="btn" data-close>Cancel</button><a class="btn primary" href="${esc(url)}" target="_blank" rel="noopener noreferrer" style="text-decoration:none">Open WhatsApp to send ${icon('external')}</a></div>`);}
function download(filename,text,type){let a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function csv(s){let v=String(s??'');if(/^[=+@\-\t\r]/.test(v))v="'"+v;return '"'+v.replaceAll('"','""')+'"';}
function exportReport(){if(!can('exportReports')){toast('This role cannot export reports.');return;}let rows=[['Project','Code','Lead','Module','Task','Consultant','Status','Due','Priority','Visit requests','Instructions'],...data.tasks.filter(canViewTask).map(t=>[project(t.project)?.name,project(t.project)?.code,person(project(t.project)?.lead).name,t.module,t.title,person(t.assignee).name,t.status,t.due,t.priority,t.visits,t.notes])];download(`implementation-report-${today()}.csv`,'\uFEFF'+rows.map(r=>r.map(csv).join(',')).join('\r\n'),'text/csv;charset=utf-8');toast('Project report exported.');}
function calendarExport(id){let m=data.meetings.find(m=>m.id===id);if(!m||!canViewMeeting(m))return;let start=new Date(`${m.date}T${m.hoursOnly?'Hours only':m.time}:00+03:00`),end=new Date(start.getTime()+m.duration*60000);let date=d=>d.toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');let ie=s=>String(s).replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');download('meeting.ics',['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Implement//ERP Delivery//EN','BEGIN:VEVENT','UID:'+m.id+'@implement','DTSTAMP:'+date(new Date()),'DTSTART:'+date(start),'DTEND:'+date(end),'SUMMARY:'+ie(m.title+' · '+project(m.project)?.name),'LOCATION:'+ie(m.location),'DESCRIPTION:'+ie(m.notes),'END:VEVENT','END:VCALENDAR'].join('\r\n'),'text/calendar');}
document.addEventListener('click',e=>{const b=e.target.closest('button,[data-project]');if(!b)return;if(b.hasAttribute('data-close')){$('#modal').close();return;}if(b.dataset.deleteProject){confirmDeleteProject(b.dataset.deleteProject);return;}if(b.dataset.confirmDeleteProject){deleteProject(b.dataset.confirmDeleteProject);return;}if(b.dataset.deleteMeeting){confirmDeleteMeeting(b.dataset.deleteMeeting);return;}if(b.dataset.confirmDeleteMeeting){deleteMeeting(b.dataset.confirmDeleteMeeting);return;}if(b.dataset.deleteTask){confirmDeleteTask(b.dataset.deleteTask);return;}if(b.dataset.confirmDeleteTask){deleteTask(b.dataset.confirmDeleteTask);return;}if(b.dataset.whatsappTask){whatsAppTask(b.dataset.whatsappTask);return;}if(b.dataset.whatsappEditMember){$('#modal').close();memberForm(b.dataset.whatsappEditMember);return;}if(b.dataset.editMember){memberForm(b.dataset.editMember);return;}if(b.dataset.toggleMember){toggleMember(b.dataset.toggleMember);return;}if(b.dataset.nav){navigate(b.dataset.nav);return;}if(b.dataset.project){navigate('detail',b.dataset.project);return;}if(b.dataset.task){taskDetail(b.dataset.task);return;}if(b.dataset.meeting){meetingDetail(b.dataset.meeting);return;}if(b.dataset.ics){calendarExport(b.dataset.ics);return;}if(b.dataset.tab){state.tab=b.dataset.tab;renderView();return;}if(b.dataset.consultant){state.role='consultant';state.consultant=b.dataset.consultant;navigate('tasks');return;}switch(b.dataset.action){case'add-member':memberForm();break;case'menu':$('.sidebar').classList.toggle('open');break;case'new-project':if(can('createProjects'))newProject();break;case'new-task':if(roleAllows('assignTasks'))newTask(b.dataset.for);break;case'new-meeting':if(roleAllows('scheduleMeetings'))newMeeting();break;case'export':exportReport();break;case'review-visits':state.taskFilter='More sessions needed';state.projectFilter='all';state.moduleFilter='all';navigate('tasks');break;case'task-layout':state.taskLayout=state.taskLayout==='list'?'cards':'list';renderView();break;}});
document.addEventListener('change',e=>{let t=e.target;switch(t.id){case'roleSelect':state.role=t.value==='manager'?'manager':'consultant';if(state.role==='consultant')state.consultant=t.value;state.taskFilter='all';state.projectFilter='all';state.moduleFilter='all';navigate(state.role==='manager'?'overview':'tasks');break;case'taskProject':state.projectFilter=t.value;renderView();break;case'taskStatus':state.taskFilter=t.value;renderView();break;case'taskModule':state.moduleFilter=t.value;renderView();break;case'projectTab':state.tab=t.value;renderView();break;case'projectLead':if(can('manageModules',state.project)){project(state.project).lead=t.value;activity(t.value,'became project in charge',state.project);renderView();toast('Project lead updated.');}break;}
 if(t.dataset.moduleOwner&&can('manageModules',state.project)){let p=project(state.project),m=t.dataset.moduleOwner;let old=p.modules[m];p.modules[m]=t.value;data.tasks.filter(x=>x.project===p.id&&x.module===m&&x.status!=='Completed'&&x.assignee===old).forEach(x=>x.assignee=t.value);activity(t.value,`took ownership of ${m} and its open module tasks`,p.id);renderView();toast('Module ownership and open task assignments updated.');}});
